<?php if($page==='roles'):$permissions=$pdo->query('SELECT * FROM permissions ORDER BY code')->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT permission_id FROM role_permissions WHERE role_id=?');$q->execute([$edit]);$selected=$error?(array)($_POST['permissions']??[]):$q->fetchAll(PDO::FETCH_COLUMN);$groups=[];foreach($permissions as $p)$groups[explode('.',$p['code'])[0]][]=$p;?><h3 style="margin:25px 0 15px">Permissions</h3><p class="hint">Enable “View” together with the actions that should be available. Role editing allows users to assign and configure roles.</p><div class="permissions"><?php foreach($groups as $group=>$perms):?><fieldset><legend><?=h(ucfirst($group))?></legend><?php foreach($perms as $p):?><label><input type="checkbox" name="permissions[]" value="<?=$p['id']?>" <?=in_array($p['id'],$selected)?'checked':''?>><?=h($p['label'])?></label><?php endforeach;?></fieldset><?php endforeach;?></div><?php endif;?><div class="form-actions"><button class="button primary">Save <?=$singular?></button></div></form></section><?php endif;?></div><?php endif;?>
